-		sec_alg_skcipher_exit(tfm);
-		return ret;
-	}
-	ctx->queue->havesoftqueue = true;
-
-	return 0;
-}
-
-static void sec_alg_skcipher_exit_with_queue(struct crypto_skcipher *tfm)
-{
-	struct sec_alg_tfm_ctx *ctx = crypto_skcipher_ctx(tfm);
