-	ret = request_threaded_irq(irq, sec_isr_handle_th, sec_isr_handle,
-				   IRQF_TRIGGER_RISING, queue->name, queue);
-	if (ret) {
-		dev_err(info->dev, "request irq(%d) failed %d\n", irq, ret);
-		return ret;
-	}
-	disable_irq(irq);
-
-	return 0;
